package parser

import "strings"

// Fields splits a CSV line. Rewritten to avoid strings.Split allocations.
func Fields(line string) []string {
	out := make([]string, 0, strings.Count(line, ",")+1)
	start := 0
	for i := 0; i < len(line); i++ {
		if line[i] == ',' {
			out = append(out, line[start:i])
			start = i + 1
		}
	}
	return append(out, line[start:])
}
== pricing/pricing.go
package pricing

type Item struct {
	Name  string
	Cents int
	Qty   int
}

type Cart struct {
	Items    []*Item
	Discount *Discount
}

type Discount struct {
	Percent int
}

// Total returns the cart total in cents after discount.
func (c *Cart) Total() int {
	sum := 0
	for _, it := range c.Items {
		sum += it.Cents * it.Qty
	}
	return sum - sum*c.Discount.Percent/100
}

// ApplyDiscount returns cents reduced by percent, never below zero.
func ApplyDiscount(cents, percent int) int {
	if percent > 100 {
		percent = 100
	}
	return cents - cents*percent/100
}
